public enum CustomerType { Regular, Loyal, Employee }

public record OrderLine(string Sku, decimal UnitPrice, int Quantity);

public record Order(CustomerType Customer, IReadOnlyList<OrderLine> Lines);

public static class PriceCalculator
{
    // To add a customer type: add it to CustomerType, write its ICustomerDiscount, register it here.
    private static readonly IReadOnlyDictionary<CustomerType, ICustomerDiscount> Discounts =
        new ICustomerDiscount[]
        {
            new LoyalDiscount(),
            new EmployeeDiscount(),
        }.ToDictionary(d => d.Customer);

    public static decimal Total(Order order)
    {
        var subtotal = order.Lines.Sum(l => l.UnitPrice * l.Quantity);
        var discount = Discounts.TryGetValue(order.Customer, out var d) ? d.DiscountOn(subtotal) : 0m;
        return subtotal - discount;
    }
}

